async function incrementUsage(env, userId) {
  try {
    const res = await env.DB.prepare("UPDATE users SET message_count = message_count + 1 WHERE user_id = ?")
      .bind(userId)
      .run();
    
    // Ensure the user was actually registered. If 0 rows were updated, register them dynamically.
    if (res && res.meta && res.meta.changes === 0) {
      console.warn(`[REG_SHIELD] User ${userId} was not registered during usage increment. Rectifying...`);
      const today = getTehranTodayDate();
      await env.DB.prepare(`
        INSERT OR IGNORE INTO users (user_id, joined_at, last_interaction_date, message_count)
        VALUES (?, ?, ?, 1)
      `).bind(userId, Date.now(), today).run();
    }
  } catch (e) {
    console.error("DB Increment Error", e);
    await logToAdmin(env, {
      level: "error",
      fn: "incrementUsage",
      event: "DB_WRITE_FAILED",
      message: "خطا در افزایش شمارنده پیام کاربر (Database Write Error)",
      error: e,
      extra: { user_id: userId }
    }).catch(() => {});
  }
}

function arrayBufferToBase64(buffer) {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function isolatedTelegramHtmlParser(text) {
  if (!text) return "";
  let out = String(text).trim();

  // 1. حذف بک‌تیک‌های مارک‌داون (اگر هوش مصنوعی کد را داخل بلوک ```html گذاشته باشد)
  out = out.replace(/^```[a-z]*\n?/i, "").replace(/\n?```$/i, "");

  // 2. تبدیل تگ‌های ساختاری نامعتبر تلگرام به معادل‌های متنی/مجاز
  out = out.replace(/<br\s*\/?>/gi, "\n");
  out = out.replace(/<\/?p[^>]*>/gi, "\n\n");
  out = out.replace(/<\/?div[^>]*>/gi, "\n");
  // تبدیل هدرها به متن ضخیم
  out = out.replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi, "\n<b>$1</b>\n");
  // تبدیل آیتم‌های لیست به بولت‌پوینت
  out = out.replace(/<li[^>]*>(.*?)<\/li>/gi, "• $1\n");
  out = out.replace(/<\/?(ul|ol)[^>]*>/gi, "");

  // 3. تبدیل تگ‌های جایگزین به تگ‌های استاندارد تلگرام
  out = out.replace(/<strong>(.*?)<\/strong>/gi, "<b>$1</b>");
  out = out.replace(/<em>(.*?)<\/em>/gi, "<i>$1</i>");
  out = out.replace(/<del>(.*?)<\/del>/gi, "<s>$1</s>");

  // 4. محافظت از تگ‌های مجاز تلگرام
  const allowedTags = ["b", "i", "u", "s", "code", "pre", "blockquote", "a"];
  const tokens = [];
  
  // محافظت از تگ <a>
  out = out.replace(/<a\s+href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gi, (match, url, content) => {
    tokens.push(`<a href="${url.replace(/&/g, "&amp;")}">`);
    tokens.push(`</a>`);
    const openIdx = tokens.length - 2;
    const closeIdx = tokens.length - 1;
    return `%%T_${openIdx}%%${content}%%T_${closeIdx}%%`;
  });

  // محافظت از بقیه تگ‌ها
  allowedTags.filter(t => t !== 'a').forEach(tag => {
    const openRegex = new RegExp(`<${tag}>`, "gi");
    const closeRegex = new RegExp(`<\/${tag}>`, "gi");
    out = out.replace(openRegex, () => {
      tokens.push(`<${tag}>`);
      return `%%T_${tokens.length - 1}%%`;
    });
    out = out.replace(closeRegex, () => {
      tokens.push(`</${tag}>`);
      return `%%T_${tokens.length - 1}%%`;
    });
  });

  // 5. پاک کردن تمام تگ‌های باقیمانده و فرار دادن کاراکترهای زاویه‌دار
  out = out.replace(/<[^>]+>/g, ""); 
  out = out.replace(/</g, "&lt;").replace(/>/g, "&gt;"); 
  
  // 6. بازگردانی تگ‌های مجاز
  out = out.replace(/%%T_(\d+)%%/g, (m, idx) => tokens[Number(idx)] || "");

  // 7. پاکسازی فاصله‌ها و خطوط خالی مکرر
  out = out.replace(/\n{3,}/g, "\n\n");

  // 8. پشته‌بندی و بستن خودکار تگ‌های رها شده (Auto-Balancer)
  const tagStack = [];
  const tagRegex = /<\/?([a-z]+)[^>]*>/gi;
  let match;
  while ((match = tagRegex.exec(out)) !== null) {
    const tag = match[1].toLowerCase();
    if (match[0].startsWith("</")) {
      if (tagStack.length > 0 && tagStack[tagStack.length - 1] === tag) {
        tagStack.pop();
      }
    } else {
      tagStack.push(tag);
    }
  }
  while (tagStack.length > 0) {
    out += `</${tagStack.pop()}>`;
  }

  return out.trim();
}

async function getActiveGeminiKey(env) {
  if (env.DB) {
    try {
      const row = await env.DB.prepare(`
        SELECT key_value FROM gemini_api_keys 
        WHERE status = 'active' 
        ORDER BY health_score DESC, last_used ASC 
        LIMIT 1
      `).first();
      if (row && row.key_value) {
        return row.key_value;
      }
    } catch (e) {
      console.error("D1 getActiveGeminiKey Error:", e);
    }
  }
  // فال‌بک نهایی به متغیر محیطی در صورت نبود دیتابیس
  const geminiRawKeys = String(env.GEMINI_API_KEY || "").split(",").map(k => k.trim()).filter(Boolean);
  return geminiRawKeys.length > 0 ? geminiRawKeys[0] : "";
}


